def populateImagesFromSurveys(self, surveys=dss2 + twomass):
        """
        Load images from archives.
        """
        self.images = []
        for survey in surveys:
            try:
                self.images += survey.images
            except AttributeError:
                pass
        self.images.sort(key=lambda x: x.name)

